    hp:{label:'HP — diagnostyka sprzętu UEFI i 24-cyfrowy Failure ID',url:'https://support.hp.com/pl-pl/help/hp-pc-hardware-diagnostics'},
    hpTests:{label:'HP — testy sprzętowe i dziennik Failure ID',url:'https://support.hp.com/pl-pl/document/ish_3042082-2941190-16'},
